using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// How the fractional part of a number is read out by
/// <see cref="Converters.INumberToWordsConverter.ConvertWithoutCurrency(decimal)"/>.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum DecimalReadingMode
{
    /// <summary>
    /// Read the fraction as a whole number of <see cref="SettingsModel.DecimalPlaces"/> digits,
    /// the way money is read: <c>1.5</c> becomes "ONE POINT FIFTY" (fifty hundredths).
    /// This is the default and matches how the currency format reads minor units.
    /// </summary>
    Fraction = 0,

    /// <summary>
    /// Read the fraction digit by digit, the way a plain number is normally spoken:
    /// <c>1.5</c> becomes "ONE POINT FIVE" and <c>1.25</c> becomes "ONE POINT TWO FIVE".
    /// Digits beyond <see cref="SettingsModel.DecimalPlaces"/> are still rounded away.
    /// </summary>
    Digits = 1,
}

/// <summary>
/// Formatting rules for a locale.
/// </summary>
public class SettingsModel
{
    /// <summary>
    /// Gets or sets a value indicating whether the word for "one" is dropped in front of the
    /// thousands scale word (Turkish <c>BİN</c> rather than <c>BİR BİN</c>, French <c>MILLE</c>
    /// rather than <c>UN MILLE</c>). Only affects the thousands group.
    /// </summary>
    [JsonPropertyName("skipOneForThousand")]
    public bool SkipOneForThousand { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether special words are used for 11–19.
    /// </summary>
    /// <remarks>
    /// Leave unset (the default) to decide automatically: teens are used whenever
    /// <see cref="SpecialNumbersModel.Teens"/> is supplied. Set it to <see langword="false"/>
    /// to force regular construction even though teens are present.
    /// </remarks>
    [JsonPropertyName("useTeens")]
    public bool? UseTeens { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether <see cref="NumbersModel.ExactHundreds"/> also
    /// applies to groups followed by a scale word. Defaults to <see langword="true"/>.
    /// </summary>
    /// <remarks>
    /// Only applies to <see cref="ScaleKind.Adjective"/> scale words; in front of a
    /// <see cref="ScaleKind.Noun"/> the exact form is always used, because the numeral
    /// phrase ends there. Spanish keeps the exact form everywhere (<c>CIEN MIL</c>), so it
    /// leaves this on. French drops the plural before a numeral adjective (<c>DEUX CENTS</c>
    /// but <c>DEUX CENT MILLE</c>), so it sets this to <see langword="false"/> — and still
    /// gets <c>DEUX CENTS MILLIONS</c>.
    /// </remarks>
    [JsonPropertyName("useExactHundredsBeforeScale")]
    public bool UseExactHundredsBeforeScale { get; set; } = true;

    /// <summary>
    /// Gets or sets a value indicating whether <see cref="SpecialNumbersModel.SpecialBeforeScale"/>
    /// also applies in front of a noun — a scale word of kind <see cref="ScaleKind.Noun"/>,
    /// or a currency name. Defaults to <see langword="false"/>.
    /// </summary>
    /// <remarks>
    /// Spanish apocopates in front of any noun: <c>1 = UNO</c> on its own but
    /// <c>UN MILLÓN</c> and <c>UN EURO</c>, <c>21 = VEINTIUNO</c> but
    /// <c>VEINTIÚN MILLONES</c> and <c>VEINTIÚN EUROS</c>. French does not, which is what
    /// keeps <c>QUATRE-VINGTS MILLIONS</c> plural. Overrides in front of an
    /// <see cref="ScaleKind.Adjective"/> scale word apply regardless of this setting.
    /// </remarks>
    [JsonPropertyName("apocopateBeforeNoun")]
    public bool ApocopateBeforeNoun { get; set; }

    /// <summary>
    /// Gets or sets a word inserted between the number and the currency name when the
    /// number ends in a <see cref="ScaleKind.Noun"/> scale word. Optional.
    /// </summary>
    /// <remarks>
    /// Spanish requires it: <c>UN MILLÓN DE EUROS</c>, but <c>UN MILLÓN QUINIENTOS MIL
    /// EUROS</c> without it, because there the number ends in <c>MIL</c>.
    /// </remarks>
    [JsonPropertyName("nounScaleLinkWord")]
    public string? NounScaleLinkWord { get; set; }

    /// <summary>
    /// Gets or sets the word placed in front of negative numbers.
    /// </summary>
    [JsonPropertyName("negativeWord")]
    public string NegativeWord { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the word used for zero.
    /// </summary>
    [JsonPropertyName("zeroWord")]
    public string ZeroWord { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the template used by <c>Convert</c>. Supports the placeholders
    /// <c>{whole}</c>, <c>{major}</c>, <c>{decimal}</c> and <c>{minor}</c>.
    /// </summary>
    [JsonPropertyName("currencyFormat")]
    public string CurrencyFormat { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the template used by <c>ConvertWithoutCurrency</c>. Supports the
    /// placeholders <c>{whole}</c> and <c>{decimal}</c>.
    /// </summary>
    [JsonPropertyName("numberFormat")]
    public string NumberFormat { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets how many fractional digits are kept. Defaults to 2 (minor currency
    /// units). Use 0 for currencies without a minor unit and 3 for currencies such as
    /// the Tunisian dinar. Must be between 0 and 6.
    /// </summary>
    [JsonPropertyName("decimalPlaces")]
    public int DecimalPlaces { get; set; } = 2;

    /// <summary>
    /// Gets or sets how the fractional part is read by <c>ConvertWithoutCurrency</c>.
    /// Defaults to <see cref="DecimalReadingMode.Fraction"/>. The currency format always
    /// reads the fraction as minor units regardless of this setting.
    /// </summary>
    [JsonPropertyName("decimalReading")]
    public DecimalReadingMode DecimalReading { get; set; } = DecimalReadingMode.Fraction;

    /// <summary>
    /// No longer used. The ones digit is always written; the separator between the tens
    /// and ones word comes from <see cref="SpecialNumbersModel.CompoundSeparator"/>.
    /// </summary>
    [Obsolete("Has no effect. The ones digit is always written; set SpecialNumbers.CompoundSeparator to control the separator. This property will be removed in 3.0.")]
    [JsonPropertyName("useCompoundNumbers")]
    public bool UseCompoundNumbers { get; set; }

    /// <summary>
    /// No longer used. Whether a locale says "one hundred" or just "hundred" is decided by
    /// the value stored at index 1 of <see cref="NumbersModel.Hundreds"/>.
    /// </summary>
    [Obsolete("Has no effect. Set Numbers.Hundreds[1] to the desired wording instead. This property will be removed in 3.0.")]
    [JsonPropertyName("skipOneForHundred")]
    public bool SkipOneForHundred { get; set; }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// Represents the complete localization ruleset for one language: its number
/// words, its formatting settings and the currencies it knows how to name.
/// </summary>
public class LocalizationModel
{
    /// <summary>
    /// Gets or sets the default currency used by <c>Convert</c> when no override is supplied.
    /// </summary>
    /// <remarks>
    /// Prefer <see cref="DefaultCurrency"/> when the currency is already listed in
    /// <see cref="Currencies"/>; naming it twice is how the two copies drift apart.
    /// </remarks>
    [JsonPropertyName("currency")]
    public CurrencyModel? Currency { get; set; }

    /// <summary>
    /// Gets or sets the key into <see cref="Currencies"/> naming the default currency, as
    /// an alternative to spelling it out again in <see cref="Currency"/>. Ignored when
    /// <see cref="Currency"/> is set.
    /// </summary>
    [JsonPropertyName("defaultCurrency")]
    public string? DefaultCurrency { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether this localization is kept only for
    /// backwards compatibility. Deprecated localizations still resolve when named
    /// exactly, but are excluded from
    /// <see cref="Converters.NumberToWordsConverter.SupportedCultures"/> and never
    /// selected by language fallback.
    /// </summary>
    [JsonPropertyName("deprecated")]
    public bool Deprecated { get; set; }

    /// <summary>
    /// Gets or sets additional currencies this locale can name, keyed by ISO 4217 code
    /// (for example <c>"EUR"</c>). Lets a single locale file serve several currencies
    /// instead of duplicating the whole file per currency.
    /// </summary>
    [JsonPropertyName("currencies")]
    public Dictionary<string, CurrencyModel>? Currencies { get; set; }

    /// <summary>
    /// Gets or sets the number words for this locale.
    /// </summary>
    [JsonPropertyName("numbers")]
    public NumbersModel? Numbers { get; set; }

    /// <summary>
    /// Gets or sets the formatting settings for this locale.
    /// </summary>
    [JsonPropertyName("settings")]
    public SettingsModel Settings { get; set; } = new();

    /// <summary>
    /// Gets or sets the irregular number words for this locale.
    /// </summary>
    [JsonPropertyName("specialNumbers")]
    public SpecialNumbersModel? SpecialNumbers { get; set; }

    /// <summary>
    /// Initializes a new instance of the <see cref="LocalizationModel"/> class.
    /// </summary>
    public LocalizationModel()
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="LocalizationModel"/> class.
    /// </summary>
    /// <param name="currency">The default currency.</param>
    /// <param name="numbers">The number words.</param>
    /// <param name="settings">Optional formatting settings.</param>
    public LocalizationModel(CurrencyModel currency, NumbersModel numbers, SettingsModel? settings = null)
    {
        Currency = currency;
        Numbers = numbers;
        Settings = settings ?? new SettingsModel();
    }
}

using System.Globalization;

namespace NumWordify.Models;

/// <summary>
/// Everything that shapes one conversion, gathered into a single object.
/// </summary>
/// <remarks>
/// The extension methods offer an overload per combination of culture, currency and
/// localization, which stops scaling once a third dimension appears. Prefer this type
/// when you need a combination the overloads do not cover, or when the settings come
/// from configuration rather than from a call site.
/// </remarks>
public sealed class WordifyOptions
{
    /// <summary>
    /// Gets or sets the culture code to convert with. Ignored when
    /// <see cref="Localization"/> is set. Defaults to <c>"en-US"</c>.
    /// </summary>
    public string Culture { get; set; } = "en-US";

    /// <summary>
    /// Gets or sets a localization to use instead of an embedded one. Takes precedence
    /// over <see cref="Culture"/>.
    /// </summary>
    public LocalizationModel? Localization { get; set; }

    /// <summary>
    /// Gets or sets a currency that replaces the locale default. Takes precedence over
    /// <see cref="CurrencyCode"/>.
    /// </summary>
    public CurrencyModel? Currency { get; set; }

    /// <summary>
    /// Gets or sets an ISO 4217 code selecting one of the currencies the locale — or
    /// <see cref="Localization"/>, when set — defines, for example <c>"EUR"</c>.
    /// Ignored when <see cref="Currency"/> is set.
    /// </summary>
    public string? CurrencyCode { get; set; }

    /// <summary>
    /// Sets <see cref="Culture"/> from a <see cref="CultureInfo"/>.
    /// </summary>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <returns>The same options instance, so calls can be chained.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="cultureInfo"/> is <see langword="null"/>.</exception>
    public WordifyOptions WithCulture(CultureInfo cultureInfo)
    {
        if (cultureInfo is null)
            throw new ArgumentNullException(nameof(cultureInfo));

        Culture = cultureInfo.Name;
        return this;
    }
}

using System.Globalization;
using NumWordify.Converters;
using NumWordify.Models;

namespace NumWordify.Extensions;

/// <summary>
/// Converts <see cref="decimal"/> values to words.
/// </summary>
/// <remarks>
/// Each call builds a converter, but the parsed localization behind it is cached for the
/// process, so this is cheap enough for per-row use. Constructing one
/// <see cref="NumberToWordsConverter"/> and reusing it is still slightly faster and is
/// safe from any number of threads.
/// </remarks>
public static class DecimalExtensions
{
    /// <summary>
    /// Converts a number to words with currency, using the given culture.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="culture">The culture code. Defaults to <c>"en-US"</c>.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, string culture = "en-US") =>
        new NumberToWordsConverter(culture).Convert(number);

    /// <summary>
    /// Converts a number to words without currency, using the given culture.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="culture">The culture code. Defaults to <c>"en-US"</c>.</param>
    /// <returns>The number in words, without currency.</returns>
    public static string ToWordsWithoutCurrency(this decimal number, string culture = "en-US") =>
        new NumberToWordsConverter(culture).ConvertWithoutCurrency(number);

    /// <summary>
    /// Converts a number to words with currency, using the given culture.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, CultureInfo cultureInfo) =>
        new NumberToWordsConverter(cultureInfo).Convert(number);

    /// <summary>
    /// Converts a number to words without currency, using the given culture.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <returns>The number in words, without currency.</returns>
    public static string ToWordsWithoutCurrency(this decimal number, CultureInfo cultureInfo) =>
        new NumberToWordsConverter(cultureInfo).ConvertWithoutCurrency(number);

    /// <summary>
    /// Converts a number to words with currency, overriding the locale currency.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="culture">The culture code.</param>
    /// <param name="currency">The currency that replaces the locale default.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, string culture, CurrencyModel currency) =>
        new NumberToWordsConverter(culture, currency).Convert(number);

    /// <summary>
    /// Converts a number to words with currency, overriding the locale currency.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <param name="currency">The currency that replaces the locale default.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, CultureInfo cultureInfo, CurrencyModel currency) =>
        new NumberToWordsConverter(cultureInfo, currency).Convert(number);

    /// <summary>
    /// Converts a number to words with currency, selecting one of the currencies the
    /// locale defines.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="culture">The culture code.</param>
    /// <param name="currencyCode">An ISO 4217 code such as <c>"EUR"</c>.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, string culture, string currencyCode) =>
        new NumberToWordsConverter(culture, currencyCode).Convert(number);

    /// <summary>
    /// Converts a number to words with currency, selecting one of the currencies the
    /// locale defines.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <param name="currencyCode">An ISO 4217 code such as <c>"EUR"</c>.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, CultureInfo cultureInfo, string currencyCode) =>
        new NumberToWordsConverter(cultureInfo, currencyCode).Convert(number);

    /// <summary>
    /// Converts a number to words with currency, using a localization you supply.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="localization">The localization ruleset.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, LocalizationModel localization) =>
        new NumberToWordsConverter(localization).Convert(number);

    /// <summary>
    /// Converts a number to words with currency, using a localization you supply and
    /// overriding its currency.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="localization">The localization ruleset.</param>
    /// <param name="currency">The currency that replaces the model default.</param>
    /// <returns>The number in words, with currency.</returns>
    public static string ToWords(this decimal number, LocalizationModel localization, CurrencyModel currency) =>
        new NumberToWordsConverter(localization, currency).Convert(number);

    /// <summary>
    /// Converts a number to words without currency, using a localization you supply.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="localization">The localization ruleset.</param>
    /// <returns>The number in words, without currency.</returns>
    public static string ToWordsWithoutCurrency(this decimal number, LocalizationModel localization) =>
        new NumberToWordsConverter(localization).ConvertWithoutCurrency(number);

    /// <summary>
    /// Converts a number to words with currency, using the given options.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="options">Culture, localization and currency settings.</param>
    /// <returns>The number in words, with currency.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="options"/> is <see langword="null"/>.</exception>
    public static string ToWords(this decimal number, WordifyOptions options) =>
        CreateConverter(options).Convert(number);

    /// <summary>
    /// Converts a number to words without currency, using the given options.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="options">Culture and localization settings. Currency settings are ignored.</param>
    /// <returns>The number in words, without currency.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="options"/> is <see langword="null"/>.</exception>
    public static string ToWordsWithoutCurrency(this decimal number, WordifyOptions options) =>
        CreateConverter(options).ConvertWithoutCurrency(number);

    private static NumberToWordsConverter CreateConverter(WordifyOptions options)
    {
        if (options is null)
            throw new ArgumentNullException(nameof(options));

        if (options.Localization is { } localization)
        {
            if (options.Currency is { } modelCurrency)
                return new NumberToWordsConverter(localization, modelCurrency);

            // Honouring Currency but silently dropping CurrencyCode would make the same
            // mistake an error on one path and invisible on the other.
            return options.CurrencyCode is { } modelCurrencyCode
                ? new NumberToWordsConverter(localization, modelCurrencyCode)
                : new NumberToWordsConverter(localization);
        }

        if (options.Currency is { } currency)
            return new NumberToWordsConverter(options.Culture, currency);

        if (options.CurrencyCode is { } currencyCode)
            return new NumberToWordsConverter(options.Culture, currencyCode);

        return new NumberToWordsConverter(options.Culture);
    }
}

using System.Globalization;
using System.Text.RegularExpressions;
using NumWordify.Exceptions;
using NumWordify.Models;

namespace NumWordify.Converters;

/// <summary>
/// Converts numbers to their word representation using a localization ruleset.
/// </summary>
/// <remarks>
/// <para>
/// Instances are immutable and stateless: conversion keeps no per-call state on the
/// object, so a single converter can be shared freely between threads and registered as
/// a singleton. Localizations loaded from a culture name are parsed once and cached for
/// the process, which makes constructing a converter cheap enough to do per call.
/// </para>
/// <para>
/// The one caveat applies to <see cref="LocalizationModel"/> instances you build
/// yourself: the converter keeps a reference rather than a copy, so the model must not
/// be mutated after it has been handed over.
/// </para>
/// </remarks>
public sealed class NumberToWordsConverter : INumberToWordsConverter
{
    private const string CustomLocalizationSource = "caller-supplied LocalizationModel";

    // The captured leading space lets an empty placeholder take its own separator with
    // it, instead of leaving a double space behind for a blanket whitespace collapse to
    // clean up — which would also eat separators a locale meant to keep.
    private static readonly Regex PlaceholderPattern = new(
        @"( ?)\{(whole|decimal|major|minor)\}",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private readonly LocalizationModel _localization;
    private readonly CurrencyModel? _overriddenCurrency;
    private readonly string _requestedCulture;
    private readonly string _resolvedCulture;
    private readonly bool _localeCurrencyApplies;

    /// <summary>
    /// Gets the culture names shipped with the library, excluding deprecated ones.
    /// </summary>
    public static IReadOnlyList<string> SupportedCultures => LocalizationLoader.SupportedCultures;

    /// <summary>
    /// Determines whether the library can convert numbers for the given culture.
    /// </summary>
    /// <param name="culture">The culture code to test, for example <c>"en-US"</c>.</param>
    /// <returns><see langword="true"/> when a localization resolves for the culture.</returns>
    /// <remarks>
    /// Useful before handing over <see cref="CultureInfo.CurrentCulture"/>, which is not
    /// guaranteed to be one of the supported cultures. A culture can resolve through
    /// language fallback — <c>es-MX</c> resolves to the Spanish number words — in which
    /// case the locale's default currency does not apply and must be supplied explicitly.
    /// </remarks>
    public static bool IsCultureSupported(string? culture) => LocalizationLoader.IsSupported(culture);

    /// <summary>
    /// Determines whether the library can convert numbers for the given culture.
    /// </summary>
    /// <param name="cultureInfo">The culture to test.</param>
    /// <returns><see langword="true"/> when a localization resolves for the culture.</returns>
    public static bool IsCultureSupported(CultureInfo? cultureInfo) =>
        cultureInfo is not null && LocalizationLoader.IsSupported(cultureInfo.Name);

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a culture.
    /// </summary>
    /// <param name="culture">The culture code, for example <c>"en-US"</c>. Matching is
    /// case-insensitive and falls back to another variant of the same language.</param>
    /// <exception cref="ArgumentNullException"><paramref name="culture"/> is <see langword="null"/>.</exception>
    /// <exception cref="ArgumentException"><paramref name="culture"/> is empty or whitespace.</exception>
    /// <exception cref="LocalizationNotFoundException">No localization matches the culture.</exception>
    /// <exception cref="InvalidLocalizationException">The localization resource is invalid.</exception>
    public NumberToWordsConverter(string culture)
    {
        var resolved = LocalizationLoader.Resolve(culture);

        _localization = resolved.Model;
        _requestedCulture = culture;
        _resolvedCulture = resolved.CultureName;
        _localeCurrencyApplies = resolved.RegionMatches;
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a culture.
    /// </summary>
