        // "DEUX CENTS MILLIONS" but drops it in "DEUX CENT MILLE".
        var endsNumeralPhrase = scale == 0 || KindOf(scale) == ScaleKind.Noun;

        if (endsNumeralPhrase || _localization.Settings.UseExactHundredsBeforeScale)
