// "bin" rather than "bir bin", "mille" rather than "un mille".
private string? DropOneBeforeThousand(int remainder, int groupValue, int scale) =>
    scale == 1 && groupValue == 1 && remainder == 1 && _localization.Settings.SkipOneForThousand
        ? string.Empty
